<template><view class="wrap"><view class="balance"><text>我的积分</text><text class="num">{{ summary.pointsBalance }}</text><text>积分</text><view class="meta">累计获得 {{summary.totalEarn}} · 已使用 {{summary.totalUsed}}</view></view><view class="card"><view class="title">积分明细</view><view v-for="x in logs" :key="x.id" class="row"><view><text>{{x.remark||x.changeType||'积分变动'}}</text><text class="time">{{x.createdAt||''}}</text></view><text :class="Number(x.amount)>=0?'plus':'minus'">{{Number(x.amount)>0?'+':''}}{{x.amount}}</text></view><view v-if="error" class="error">{{error}}</view><view v-else-if="!loading&&!logs.length" class="empty">暂无积分明细</view><button v-if="hasMore" class="more" :loading="loading" @tap="loadMore">加载更多</button></view></view></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import {apiRequest} from '@mall/uni-shared';const summary=reactive<any>({pointsBalance:0,totalEarn:0,totalUsed:0}),logs=ref<any[]>([]),error=ref(''),loading=ref(false),page=ref(1),hasMore=ref(false);async function load(reset=false){if(loading.value)return;if(reset){page.value=1;logs.value=[]}loading.value=true;error.value='';try{const [s,l]:any=await Promise.all([apiRequest({url:'/api/c/points/summary'}),apiRequest({url:`/api/c/points/log?page=${page.value}&size=20`})]);Object.assign(summary,s||{});const items=Array.isArray(l)?l:l?.list??[];logs.value=reset?items:[...logs.value,...items];hasMore.value=Boolean(l?.hasMore)||items.length===20}catch(e:any){error.value=e.message||'积分加载失败'}finally{loading.value=false}}function loadMore(){page.value++;load()}load(true);</script>
<style scoped>.wrap{padding:32rpx}.balance{background:#1677ff;color:#fff;border-radius:18rpx;padding:36rpx;font-size:28rpx}.num{font-size:64rpx;font-weight:700;margin:0 12rpx}.meta{margin-top:14rpx;font-size:24rpx}.card{margin-top:24rpx;background:#fff;padding:30rpx;border-radius:16rpx}.title{font-weight:700;margin-bottom:20rpx}.row{display:flex;justify-content:space-between;padding:20rpx 0;border-bottom:1rpx solid #f5f5f5}.time{display:block;color:#999;font-size:21rpx;margin-top:8rpx}.plus{color:#52c41a}.minus,.error{color:#f5222d}.empty{color:#999;padding:30rpx 0;text-align:center}.error{padding:20rpx 0}.more{margin-top:20rpx;background:#fff;color:#1677ff;font-size:25rpx}</style>
